from hermes_tools import terminal
script = r'''
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/output/result.xlsx'
wb = load_workbook(path, data_only=False)
print('Reopened:', path)
print('Sheet names:', wb.sheetnames)
ws = wb['Task']
modified_ranges = [(12,17),(19,24),(26,31),(35,40),(42,47),(50,50)]
print('\n=== Modified cell formulas ===')
for start,end in modified_ranges:
    print(f'-- Rows {start}:{end}, H:L --')
    for r in range(start,end+1):
        vals=[]
        for c in range(8,13):
            vals.append(f'{get_column_letter(c)}{r}={ws.cell(r,c).value!r}')
        print(' | '.join(vals))
# Validation checks
errors=[]
if wb.sheetnames != ['Task','Data']:
    errors.append(f'Unexpected sheets: {wb.sheetnames}')
for start,end in [(12,17),(19,24),(26,31)]:
    for r in range(start,end+1):
        for c in range(8,13):
            v=ws.cell(r,c).value
            if not (isinstance(v,str) and v.startswith('=INDEX(') and 'MATCH($D' in v and 'Data!$D$21:$D$38' in v and 'Data!$H$4:$L$4' in v):
                errors.append(f'{get_column_letter(c)}{r} lookup formula unexpected: {v!r}')
for idx,r in enumerate(range(35,41)):
    for c in range(8,13):
        col=get_column_letter(c)
        expected=f'=({col}{12+idx}-{col}{19+idx})/{col}{26+idx}*100'
        if ws.cell(r,c).value != expected:
            errors.append(f'{col}{r} expected {expected!r}, got {ws.cell(r,c).value!r}')
for c in range(8,13):
    col=get_column_letter(c)
    expected_by_row={
        42:f'=MIN({col}35:{col}40)',
        43:f'=MAX({col}35:{col}40)',
        44:f'=MEDIAN({col}35:{col}40)',
        45:f'=AVERAGE({col}35:{col}40)',
        46:f'=PERCENTILE({col}35:{col}40,0.25)',
        47:f'=PERCENTILE({col}35:{col}40,0.75)',
        50:f'=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)',
    }
    for r, expected in expected_by_row.items():
        if ws.cell(r,c).value != expected:
            errors.append(f'{col}{r} expected {expected!r}, got {ws.cell(r,c).value!r}')
print('\nValidation:', 'PASS' if not errors else 'FAIL')
for e in errors:
    print('ERROR:', e)
'''
res=terminal('python3 - <<\'PY\'\n'+script+'\nPY', timeout=120, workdir='/root')
print(res['output'])
if res.get('exit_code') != 0: print('EXIT', res.get('exit_code'))
